//! Passive optgroup connection preserves actual identity and ownership.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=target>Fallback group<span id=tail>Tail</span></div><select id=select><optgroup id=group label=Group><option value=one>One</option></optgroup></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://optgroup-connection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn optgroup_connection_native_created_append_reorder_remove(){let(mut d,mut f,mut p)=fixture();let count=f.controls.len();run(&mut d,&mut f,&mut p,r#"var target=document.getElementById('target'),first=target.firstChild,tail=document.getElementById('tail'),x=document.createElement('optgroup');x.label='A\ud800Z';x.disabled=true;var attr=x.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});if(target.appendChild(x)!==x||x.parentNode!==target||x.ownerDocument!==document||x.label!=='A\ud800Z'||!x.disabled||x.getAttributeNode('label')!==attr)throw 'actual native connection';target.insertBefore(x,first);if(target.firstChild!==x||x.nextSibling!==first)throw 'actual reorder';target.removeChild(x);if(x.parentNode!==null||x.ownerDocument!==document||attr.ownerElement!==x||x.getAttributeNode('label')!==attr||target.firstChild!==first||target.lastChild!==tail||document.getElementById('neighbor').value!=='seed'||watch.takeRecords().length!==4)throw 'actual removal identity';"#);assert_eq!(f.controls.len(),count);}
#[test]
fn optgroup_connection_inert_insert_preserves_actual_node_attr_owner(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup'),target=document.getElementById('target');source.label='raw\udfff';source.disabled=true;var attr=source.getAttributeNode('label');target.appendChild(source);if(source.parentNode!==target||source.ownerDocument!==document||attr.ownerDocument!==document||source.getAttributeNode('label')!==attr||attr.ownerElement!==source||source.label!=='raw\udfff'||!source.disabled)throw 'actual inert connection identity';target.removeChild(source);if(source.parentNode!==null||source.ownerDocument!==document||attr.ownerDocument!==document)throw 'actual removed owner';"#);}
#[test]
fn optgroup_connection_native_clone_template_parking_roundtrip(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var target=document.getElementById('target'),source=document.createElement('optgroup');source.label='parked';source.disabled=true;var x=source.cloneNode(false),attr=x.getAttributeNode('label'),template=document.createElement('template');template.content.appendChild(x);if(x.ownerDocument!==template.content.ownerDocument||attr.ownerDocument!==x.ownerDocument||x.getAttributeNode('label')!==attr||x.label!=='parked'||!x.disabled)throw 'actual native parking';target.appendChild(template.content);if(x.parentNode!==target||x.ownerDocument!==document||attr.ownerDocument!==document||x.getAttributeNode('label')!==attr||template.content.firstChild!==null||source.label!=='parked')throw 'parking roundtrip';"#);}

#[test]
fn optgroup_connection_storage_work_copy_and_deadline_refusals_preserve_identity_and_recover(){
 for parking in [false,true]{for mode in 0..4{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if parking{
   "var target=document.createElement('template').content,source=document.getElementById('group').cloneNode(false);"
  }else{
   "var target=document.getElementById('target'),owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup');"
  });
  run(&mut d,&mut f,&mut p,"source.label='retained';source.disabled=true;var attr=source.getAttributeNode('label'),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});var originalOwner=source.ownerDocument;");
  p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);
  let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),Bridge{doc: &mut d,forms: &mut f,state: &mut p.state}.inert_node_count(),p.state.attributes.len(),p.state.detached_nodes.clone());
  let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};
  let error=p.runtime.execute("target.appendChild(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();
  assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound")||error.contains("time"),"{parking}/{mode}: {error}");
  assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),Bridge{doc: &mut d,forms: &mut f,state: &mut p.state}.inert_node_count(),p.state.attributes.len(),p.state.detached_nodes.clone()),before);
  p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();
  run(&mut d,&mut f,&mut p,"if(source.parentNode!==null||source.ownerDocument!==originalOwner||source.getAttributeNode('label')!==attr||attr.ownerElement!==source||source.label!=='retained'||!source.disabled||watch.takeRecords().length)throw 'atomic OptGroup transfer refusal';target.appendChild(source);var records=watch.takeRecords();if(source.parentNode!==target||source.ownerDocument!==target.ownerDocument||attr.ownerDocument!==target.ownerDocument||source.getAttributeNode('label')!==attr||source.label!=='retained'||!source.disabled||records.length!==1)throw 'fresh OptGroup transfer recovery '+[source.parentNode===target,source.ownerDocument===target.ownerDocument,attr.ownerDocument===target.ownerDocument,source.getAttributeNode('label')===attr,records.length].join(',');");
  assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
 }}
}


#[test]
fn optgroup_connection_saved_child_append_revalidates_origin_before_transferring_owner(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup'),target=document.getElementById('target'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);source.label='saved';var saved=frame.contentWindow.Node.prototype.appendChild,attr=source.getAttributeNode('label');");
 p.set_location(&crate::navigation::address("https://other-optgroup.test/",&crate::navigation::Location::home()).unwrap());
 let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits);p.begin_job();
 let error=p.runtime.execute("saved.call(target,source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");
 assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits),before);
 p.set_location(&crate::navigation::address("https://optgroup-connection.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();
 run(&mut d,&mut f,&mut p,"if(source.parentNode!==null||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.label!=='saved')throw 'denied transfer preserves owner';if(saved.call(target,source)!==source||source.ownerDocument!==document||source.parentNode!==target||source.getAttributeNode('label')!==attr||attr.ownerDocument!==document||source.label!=='saved')throw 'saved transfer fresh recovery';");
}



#[test]
fn optgroup_connection_factory_template_and_cloned_fragment_keep_real_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var template=document.createElement('template');var group=template.content.ownerDocument.createElementNS('http://www.w3.org/1999/xhtml','optgroup');group.label='parsed';group.disabled=true;template.content.appendChild(group);var fragment=template.content,source=fragment.firstChild,attr=source.getAttributeNode('label'),donor=fragment.cloneNode(true),copy=donor.firstChild,target=document.getElementById('target');target.appendChild(fragment);target.appendChild(donor);if(fragment.firstChild!==null||donor.firstChild!==null||source===copy||source.parentNode!==target||copy.parentNode!==target||source.ownerDocument!==document||copy.ownerDocument!==document||source.label!=='parsed'||copy.label!=='parsed'||!source.disabled||!copy.disabled||source.getAttributeNode('label')!==attr||attr.ownerDocument!==document||copy.getAttributeNode('label')===attr)throw 'parsed group fragment connection';"#);}
#[test]
fn optgroup_connection_preserves_select_rows_options_and_separate_mutation_guards(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let native=format!("{:?}",f.controls[&select].select);let count=f.controls.len();run(&mut d,&mut f,&mut p,"var target=document.getElementById('target'),select=document.getElementById('select'),inside=document.getElementById('group'),source=document.createElement('optgroup'),option=document.createElement('option');source.label='held';source.disabled=true;target.appendChild(source);target.removeChild(source);");assert_eq!(format!("{:?}",f.controls[&select].select),native);for code in ["select.appendChild(source);","select.removeChild(inside);","target.appendChild(option);"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("native control")||e.contains("DOM tree mutation")||e.contains("DOMException"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.detached_nodes.clone()),state);assert_eq!(format!("{:?}",f.controls[&select].select),native);assert_eq!(f.controls.len(),count);}p.begin_job();run(&mut d,&mut f,&mut p,"target.appendChild(source);if(source.label!=='held'||!source.disabled||source.parentNode!==target||inside.parentNode!==select)throw 'fresh ordinary connection preserves select guard';");}

#[test]
fn optgroup_connection_nonconventional_parser_select_recovery_guard_is_atomic(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var template=document.createElement('template'),fragment=template.content;");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes());p.begin_job();let e=p.runtime.execute("template.innerHTML='<optgroup label=guarded><div><optgroup></div></optgroup>';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("HTML fragment nonconventional select recovery is not implemented."),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(template.content!==fragment||fragment.firstChild!==null)throw 'parser refusal preserves actual fragment';var group=fragment.ownerDocument.createElementNS('http://www.w3.org/1999/xhtml','optgroup');group.label='factory';fragment.appendChild(group);document.getElementById('target').appendChild(fragment);if(group.ownerDocument!==document||group.label!=='factory')throw 'independent factory connection recovery';");}
